/**
 * Literature-in-english families (round 2, JAMB pool).
 *
 * Pattern-verified families quote a line and ask for the device: the verifier
 * MACHINE-CHECKS the quoted text (contains "like"/"as" for a simile, a
 * non-human subject with a human act for personification, a repeated initial
 * consonant for alliteration, an antonym pair for an oxymoron, a sound-word
 * lookup for onomatopoeia, an extreme-quantity word for hyperbole) — a wrong
 * key cannot verify against the quoted evidence.
 * Recall tables use the dual-answer contract (key + independently authored proof).
 */

import { int, pick, shuffled } from "./engine.mjs";
import { recallFamily, parseNum, pool3 } from "./families-support.mjs";

const DEVICES = ["simile", "metaphor", "personification", "alliteration", "hyperbole", "onomatopoeia", "oxymoron", "irony"];

const NON_HUMAN = ["wind", "sun", "moon", "stars", "trees", "river", "storm", "clouds", "fire", "darkness", "shadows", "leaves", "waves", "thunder", "morning", "night"];
const HUMAN_ACTS = ["whispered", "sang", "smiled", "wept", "danced", "laughed", "slept", "shouted", "knelt", "sighed", "hid", "crept", "roared", "cried", "screamed", "bowed", "waited", "woke"];
const SOUND_WORDS = ["buzz", "hiss", "clang", "splash", "crackle", "whisper", "roar", "click", "thud", "murmur", "bang", "crash", "pop", "rustle", "creak", "bubble", "clatter", "gurgle", "sizzle", "snap", "patter", "drip", "plop", "fizz", "hoot", "screech", "groan"];
const OXYMORON_PAIRS = [
  ["deafening", "silence"],
  ["bitter", "sweet"],
  ["living", "death"],
  ["open", "secret"],
  ["sweet", "sorrow"],
  ["heavy", "lightness"],
  ["cold", "fire"],
  ["timeless", "moment"],
  ["loud", "quiet"],
  ["gentle", "thunder"],
];

function isSimile(line) {
  return /\b(like|as)\b/i.test(line) && /(boy|girl|man|woman|child|bird|lion|snake|rose|sun|moon|star|angel|drum|thunder|lightning|king|queen|baby|tiger|dove|lion|knife|blade|arrow|mountain|ice|ship|wind|horse|feather|stone|lioness|cat|dog)\w*\b/i.test(line);
}
function isAlliteration(line) {
  const words = String(line).toLowerCase().replace(/[^a-z ]/g, "").split(/\s+/).filter(Boolean);
  const counts = {};
  for (const w of words) counts[w[0]] = (counts[w[0]] ?? 0) + 1;
  return Object.values(counts).some((c) => c >= 3);
}
function isPersonification(line) {
  const words = String(line).toLowerCase().replace(/[^a-z ]/g, "").split(/\s+/).filter(Boolean);
  const hasNonHuman = words.some((w) => NON_HUMAN.includes(w));
  const hasHumanAct = words.some((w) => HUMAN_ACTS.includes(w));
  return hasNonHuman && hasHumanAct;
}
function isOnomatopoeia(line) {
  const words = String(line).toLowerCase().replace(/[^a-z ]/g, "").split(/\s+/);
  return words.some((w) => SOUND_WORDS.some((s) => w.startsWith(s)));
}
function isOxymoron(line) {
  const lower = String(line).toLowerCase();
  return OXYMORON_PAIRS.some(([a, b]) => lower.includes(a) && lower.includes(b));
}
function isHyperbole(line) {
  return /\b(thousand|million|forever|endless|worlds|whole world|ocean|oceans|ages|never)\b/i.test(line);
}

const PATTERN_CHECKERS = { simile: isSimile, alliteration: isAlliteration, personification: isPersonification, onomatopoeia: isOnomatopoeia, oxymoron: isOxymoron, hyperbole: isHyperbole };

