    answer: (p) => p.device,
    stem(p) {
      return `Which literary device is demonstrated in the line: "${p.line}"`;
    },
    distractors(p, r) {
      const out = [];
      for (const c of shuffled(r, DEVICES)) {
        if (out.length === 3) break;
        if (c !== p.device && !out.includes(c)) out.push(c);
      }
      return out;
    },
    explanation(p) {
      return `${p.why} The other options describe devices not present in this line.`;
    },
    hint: () => "Read the line for its surface feature: comparison word, repeated sound, human act on a non-human subject, or sound word.",
    verify(p, chosen) {
      if (chosen !== p.device) return false;
      const checker = PATTERN_CHECKERS[p.device];
      if (!checker) return false;
      return checker(p.line) === true;
    },
